using Clock=chrono::steady_clock;
static long long nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
struct Config { string listen,root,origin,trust; int maxconn,header,ht,idle,wt,maxreq,depth,cb,gb,refill; sockaddr_in la{},oa{}; uint32_t trusted;};
static string trim(string s){size_t a=s.find_first_not_of(" \t\r"), b=s.find_last_not_of(" \t\r"); return a==string::npos?"":s.substr(a,b-a+1);}
static bool addr(const string&s,sockaddr_in& a){size_t p=s.rfind(':');if(p==string::npos||p==0||p+1==s.size())return false;string h=s.substr(0,p),q=s.substr(p+1); unsigned v=0;for(char c:q){if(c<'0'||c>'9'||v>65535)return false;v=v*10+c-'0';}if(v==0||v>65535)return false;memset(&a,0,sizeof(a));a.sin_family=AF_INET;a.sin_port=htons(v);return inet_pton(AF_INET,h.c_str(),&a.sin_addr)==1;}
static bool number(const string&s,int& v){if(s.empty())return false;long long n=0;for(char c:s){if(c<'0'||c>'9'||n>(2147483647LL-(c-'0'))/10)return false;n=n*10+c-'0';}if(!n)return false;v=n;return true;}
static bool load(const string& path,Config& c){ifstream f(path);if(!f)return false;map<string,string> m;string l;while(getline(f,l)){if(!l.empty()&&l.back()=='\r')l.pop_back();l=trim(l);if(l.empty()||l[0]=='#')continue;size_t p=l.find('=');if(p==string::npos)return false;string k=trim(l.substr(0,p)),v=trim(l.substr(p+1));if(k.empty()||m.count(k))return false;m[k]=v;} const vector<string> keys={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth","origin_address","client_burst","global_burst","refill_ms","trusted_peer"};if(m.size()!=keys.size())return false;for(auto&k:keys)if(!m.count(k))return false;c.listen=m["listen"];c.root=m["root"];c.origin=m["origin_address"];c.trust=m["trusted_peer"];struct stat st{};in_addr ip{};if(c.root.empty()||c.root[0]!='/'||stat(c.root.c_str(),&st)||!S_ISDIR(st.st_mode)||!addr(c.listen,c.la)||!addr(c.origin,c.oa)||inet_pton(AF_INET,c.trust.c_str(),&ip)!=1)return false;c.trusted=ip.s_addr;return number(m["max_connections"],c.maxconn)&&number(m["header_bytes"],c.header)&&number(m["header_timeout_ms"],c.ht)&&number(m["idle_timeout_ms"],c.idle)&&number(m["write_timeout_ms"],c.wt)&&number(m["max_requests"],c.maxreq)&&number(m["pipeline_depth"],c.depth)&&number(m["client_burst"],c.cb)&&number(m["global_burst"],c.gb)&&number(m["refill_ms"],c.refill);}
static volatile sig_atomic_t reload_flag=0;static void hup(int){reload_flag=1;}
static int ep=-1,listener=-1,rootfd=-1;static Config cfg;static string configpath;static int active=0;
static void addfd(int fd,uint32_t ev){epoll_event e{};e.events=ev;e.data.fd=fd;epoll_ctl(ep,EPOLL_CTL_ADD,fd,&e);}static void modfd(int fd,uint32_t ev){epoll_event e{};e.events=ev;e.data.fd=fd;epoll_ctl(ep,EPOLL_CTL_MOD,fd,&e);}static void delfd(int fd){epoll_ctl(ep,EPOLL_CTL_DEL,fd,nullptr);close(fd);}
static int bindlisten(const sockaddr_in&a){int s=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(s<0)return -1;int one=1;setsockopt(s,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(s,(sockaddr*)&a,sizeof(a))||listen(s,4096)){close(s);return -1;}return s;}
struct Bucket{double tokens;long long last;};static unordered_map<uint32_t,Bucket> buckets;static Bucket globalb;
static void refill(Bucket&b,int cap,long long t){if(t>b.last){b.tokens=min((double)cap,b.tokens+(double)(t-b.last)/cfg.refill);b.last=t;}}
static bool admit(uint32_t ip){long long t=nowms();auto [i,ins]=buckets.try_emplace(ip,Bucket{(double)cfg.cb,t});refill(i->second,cfg.cb,t);refill(globalb,cfg.gb,t);if(i->second.tokens<1||globalb.tokens<1)return false;i->second.tokens-=1;globalb.tokens-=1;return true;}
struct Conn {int fd=-1,up=-1,file=-1;uint32_t peer=0;string in,out,upsend,uphead;size_t op=0,usp=0;off_t off=0;long long remain=0,upremain=0;bool closeafter=false,head=false,proxy=false,upheader=false,connecting=false;int count=0;long long last=0,first=0,writeat=0;};
static unordered_map<int,Conn> conns;static unordered_map<int,int> owners;
static void closeup(Conn&c){if(c.up>=0){owners.erase(c.up);delfd(c.up);c.up=-1;}}
static void destroy(int fd){auto i=conns.find(fd);if(i==conns.end())return;Conn&c=i->second;closeup(c);if(c.file>=0)close(c.file);delfd(fd);conns.erase(i);--active;}
static string lower(string s){for(char&c:s)if(c>='A'&&c<='Z')c+=32;return s;}
static bool tokenchar(unsigned char c){return (c>='0'&&c<='9')||(c>='A'&&c<='Z')||(c>='a'&&c<='z')||strchr("!#$%&'*+-.^_`|~",c);}
static const char* reason(int s){switch(s){case 200:return "OK";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 429:return "Too Many Requests";case 431:return "Request Header Fields Too Large";case 502:return "Bad Gateway";default:return "Error";}}
static void response(Conn&c,int status,long long len,const string& body="",const string& extra="",const string& phrase=""){c.out="HTTP/1.1 "+to_string(status)+" "+(phrase.empty()?reason(status):phrase)+"\r\nContent-Length: "+to_string(len)+"\r\nConnection: "+(c.closeafter?"close":"keep-alive")+"\r\n"+extra+"\r\n";if(!c.head)c.out+=body;c.op=0;c.writeat=nowms();}
static void fail(Conn&c,int status,bool force=true){closeup(c);if(c.file>=0){close(c.file);c.file=-1;}c.proxy=false;c.remain=0;if(force)c.closeafter=true;response(c,status,0);}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;int n;unsigned x;if(c>=0xc2&&c<=0xdf){n=1;x=c&31;}else if(c>=0xe0&&c<=0xef){n=2;x=c&15;}else if(c>=0xf0&&c<=0xf4){n=3;x=c&7;}else return false;if(i+n>s.size())return false;for(int j=0;j<n;j++){unsigned char t=s[i++];if((t&0xc0)!=0x80)return false;x=(x<<6)|(t&63);}if((n==2&&x<0x800)||(n==3&&x<0x10000)||x>0x10ffff||(x>=0xd800&&x<=0xdfff))return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static bool pathdecode(const string&t,string&d){if(t.empty()||t[0]!='/'||t.find('#')!=string::npos)return false;size_t end=t.find('?');if(end==string::npos)end=t.size();for(size_t i=0;i<end;i++){unsigned char c=t[i];if(c=='%'){if(i+2>=end)return false;int a=hex(t[i+1]),b=hex(t[i+2]);if(a<0||b<0)return false;c=(a<<4)|b;i+=2;}if(c==0||c=='\\'||c<32||c==127)return false;d.push_back(c);}return utf8(d);}
static int openfile(const string&path,int&fd,long long&size){int dir=dup(rootfd);if(dir<0)return 403;size_t pos=1;vector<string> parts;while(pos<=path.size()){size_t e=path.find('/',pos);if(e==string::npos)e=path.size();string p=path.substr(pos,e-pos);if(p==".."){close(dir);return 403;}if(!p.empty()&&p!=".")parts.push_back(p);if(e==path.size())break;pos=e+1;}if(parts.empty()){close(dir);return 403;}for(size_t i=0;i<parts.size();i++){bool last=i+1==parts.size();int n=openat(dir,parts[i].c_str(),O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK|(last?0:O_DIRECTORY));if(n<0){int er=errno;struct stat st{};bool sym=fstatat(dir,parts[i].c_str(),&st,AT_SYMLINK_NOFOLLOW)==0&&S_ISLNK(st.st_mode);close(dir);return sym||er==ELOOP||er==EACCES?403:(er==ENOTDIR?403:404);}close(dir);dir=n;}struct stat st{};if(fstat(dir,&st)||!S_ISREG(st.st_mode)||(!path.empty()&&path.back()=='/')){close(dir);return 403;}fd=dir;size=st.st_size;return 200;}
static bool hasclose(const string&s){size_t p=0;while(p<=s.size()){size_t e=s.find(',',p);if(e==string::npos)e=s.size();if(lower(trim(s.substr(p,e-p)))=="close")return true;if(e==s.size())break;p=e+1;}return false;}
static void startproxy(Conn&c,const string&method,const string&uri,const string&host){int s=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(s<0){fail(c,502,false);return;}c.up=s;c.proxy=true;c.upheader=false;c.uphead.clear();c.upsend=method+" "+uri+" HTTP/1.1\r\nHost: "+host+"\r\nConnection: close\r\n\r\n";c.usp=0;c.connecting=true;owners[s]=c.fd;int r=connect(s,(sockaddr*)&cfg.oa,sizeof(cfg.oa));if(r==0)c.connecting=false;else if(errno!=EINPROGRESS){fail(c,502,false);return;}addfd(s,EPOLLOUT|EPOLLRDHUP);c.writeat=nowms();}
static void handle(Conn&c,const string&h){c.count++;c.head=false;c.closeafter=c.count>=cfg.maxreq;size_t e=h.find("\r\n");if(e==string::npos){fail(c,400);return;}string line=h.substr(0,e);size_t a=line.find(' '),b=a==string::npos?string::npos:line.find(' ',a+1);if(a==string::npos||b==string::npos||a==0||b==a+1||line.find(' ',b+1)!=string::npos){fail(c,400);return;}string method=line.substr(0,a),target=line.substr(a+1,b-a-1),version=line.substr(b+1);for(unsigned char x:method)if(!tokenchar(x)){fail(c,400);return;}if(version!="HTTP/1.1"&&version!="HTTP/1.0"){fail(c,400);return;}if(version=="HTTP/1.0")c.closeafter=true;c.head=method=="HEAD";int hosts=0,cls=0,reals=0;string host,real;bool bad=false,te=false,cc=false;size_t p=e+2;while(p<h.size()-2){size_t n=h.find("\r\n",p);if(n==string::npos){bad=true;break;}if(n==p)break;string s=h.substr(p,n-p);p=n+2;size_t colon=s.find(':');if(colon==string::npos||colon==0){bad=true;break;}for(size_t k=0;k<colon;k++)if(!tokenchar((unsigned char)s[k]))bad=true;string name=lower(s.substr(0,colon)),v=trim(s.substr(colon+1));if(name=="host"){hosts++;host=v;}else if(name=="content-length"){cls++;if(v.empty())bad=true;for(char x:v)if(x!='0')bad=true;}else if(name=="transfer-encoding")te=true;else if(name=="connection"){if(hasclose(v))cc=true;}else if(name=="x-real-ip"){reals++;real=v;}}
if(cc)c.closeafter=true;if(bad||te||cls>1){fail(c,400);return;}string decoded;if(!pathdecode(target,decoded)){fail(c,400);return;}if(method!="GET"&&method!="HEAD"){response(c,405,0);return;}if(decoded=="/health"&&(target=="/health"||target.rfind("/health?",0)==0)){response(c,200,3,"ok\n","Content-Type: text/plain\r\n");return;}if(target.rfind("/gateway/",0)==0){if(hosts!=1||host.empty()){fail(c,400);return;}uint32_t ip=c.peer;in_addr x{};if(ip==cfg.trusted&&reals==1&&inet_pton(AF_INET,real.c_str(),&x)==1)ip=x.s_addr;if(!admit(ip)){response(c,429,0);return;}startproxy(c,method,target.substr(8),host);return;}int fd=-1;long long size=0;int status=openfile(decoded,fd,size);if(status!=200){response(c,status,0);return;}response(c,200,size,"","Content-Type: application/octet-stream\r\n");if(c.head)close(fd);else{c.file=fd;c.off=0;c.remain=size;}}
static void update(Conn&c){uint32_t v=EPOLLRDHUP;bool busy=!c.out.empty()||c.file>=0||c.proxy;if(!busy)v|=EPOLLIN;if(!c.out.empty()||c.file>=0)v|=EPOLLOUT;modfd(c.fd,v);if(c.up>=0){uint32_t u=EPOLLRDHUP;if(c.connecting||c.usp<c.upsend.size())u|=EPOLLOUT;else if(!c.upheader||c.out.size()-c.op<65536)u|=EPOLLIN;modfd(c.up,u);}}
static void parseinput(Conn&c){if(!c.out.empty()||c.file>=0||c.proxy)return;if(c.in.empty()){c.first=0;return;}size_t end=c.in.find("\r\n\r\n");size_t check=end==string::npos?c.in.size():end+4;for(size_t i=0;i<check;i++){char ch=c.in[i];if(ch==0||(ch=='\n'&&(i==0||c.in[i-1]!='\r'))||(ch=='\r'&&i+1<check&&c.in[i+1]!='\n')){c.in.clear();fail(c,400);return;}}if(end!=string::npos){if(end+4>(size_t)cfg.header){c.in.clear();fail(c,431);return;}string h=c.in.substr(0,end+4);c.in.erase(0,end+4);c.first=c.in.empty()?0:nowms();handle(c,h);}else if(c.in.size()>(size_t)cfg.header){c.in.clear();fail(c,431);}}
static bool upstream_header(Conn&c){size_t end=c.uphead.find("\r\n\r\n");if(end==string::npos){if(c.uphead.size()>65536)fail(c,502,false);return false;}string h=c.uphead.substr(0,end+4),body=c.uphead.substr(end+4);c.uphead.clear();size_t e=h.find("\r\n"),a=h.find(' ');if(e==string::npos||a==string::npos||a>=e||h.substr(0,a)!="HTTP/1.1"&&h.substr(0,a)!="HTTP/1.0"||a+4>e||h[a+1]<'1'||h[a+1]>'5'||h[a+2]<'0'||h[a+2]>'9'||h[a+3]<'0'||h[a+3]>'9'||(a+4<e&&h[a+4]!=' ')){fail(c,502,false);return false;}int status=(h[a+1]-'0')*100+(h[a+2]-'0')*10+h[a+3]-'0';string phrase=a+5<=e?h.substr(a+5,e-a-5):"";for(unsigned char x:phrase)if(x<32||x==127){fail(c,502,false);return false;}int cl=0;long long len=0;bool bad=false;string extras;size_t p=e+2;while(p<end){size_t n=h.find("\r\n",p);if(n==string::npos||n>end){bad=true;break;}string line=h.substr(p,n-p);p=n+2;size_t col=line.find(':');if(col==string::npos||!col){bad=true;break;}for(size_t i=0;i<col;i++)if(!tokenchar((unsigned char)line[i]))bad=true;string name=lower(line.substr(0,col)),v=trim(line.substr(col+1));for(unsigned char x:v)if(x==0||x=='\r'||x=='\n')bad=true;if(name=="content-length"){cl++;if(v.empty())bad=true;for(char x:v){if(x<'0'||x>'9'||len>(LLONG_MAX-(x-'0'))/10){bad=true;break;}len=len*10+x-'0';}}else if(name=="transfer-encoding")bad=true;else if(name=="content-type")extras+="Content-Type: "+v+"\r\n";}
if(bad||cl!=1||status<200){fail(c,502,false);return false;}c.upheader=true;c.upremain=c.head?0:len;response(c,status,len,"",extras,phrase);if(!c.head){if((long long)body.size()>c.upremain)body.resize((size_t)c.upremain);c.out+=body;c.upremain-=body.size();}if(c.upremain==0){closeup(c);c.proxy=false;}return true;}
static void up_event(Conn&c,uint32_t ev){if(c.up<0)return;if(c.connecting&&(ev&(EPOLLOUT|EPOLLERR|EPOLLHUP))){int err=0;socklen_t n=sizeof(err);if(getsockopt(c.up,SOL_SOCKET,SO_ERROR,&err,&n)||err){fail(c,502,false);return;}c.connecting=false;}if(!c.connecting&&c.usp<c.upsend.size()&&(ev&EPOLLOUT)){ssize_t n=send(c.up,c.upsend.data()+c.usp,c.upsend.size()-c.usp,MSG_NOSIGNAL);if(n>0){c.usp+=n;c.writeat=nowms();}else if(n<0&&errno!=EAGAIN&&errno!=EWOULDBLOCK&&errno!=EINTR){fail(c,502,false);return;}}
if(c.up>=0&&c.usp==c.upsend.size()&&(ev&(EPOLLIN|EPOLLRDHUP|EPOLLHUP|EPOLLERR))){char buf[32768];for(int iter=0;iter<4&&c.up>=0;iter++){if(c.upheader&&c.out.size()-c.op>=65536)break;ssize_t n=recv(c.up,buf,sizeof(buf),0);if(n>0){c.writeat=nowms();if(!c.upheader){c.uphead.append(buf,n);if(!upstream_header(c))break;}else{size_t take=min((long long)n,c.upremain);c.out.append(buf,take);c.upremain-=take;if(c.upremain==0){closeup(c);c.proxy=false;break;}}}else if(n==0){if(!c.upheader)fail(c,502,false);else{closeup(c);c.proxy=false;if(c.upremain)c.closeafter=true;}break;}else{if(errno!=EAGAIN&&errno!=EWOULDBLOCK&&errno!=EINTR){if(!c.upheader)fail(c,502,false);else{closeup(c);c.proxy=false;c.closeafter=true;}}break;}}}}
static bool writeclient(Conn&c){while(true){if(c.op<c.out.size()){ssize_t n=send(c.fd,c.out.data()+c.op,c.out.size()-c.op,MSG_NOSIGNAL);if(n>0){c.op+=n;c.writeat=nowms();}else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK||errno==EINTR))return true;else return false;}if(c.op==c.out.size()){c.out.clear();c.op=0;}if(c.file>=0){if(c.remain){ssize_t n=sendfile(c.fd,c.file,&c.off,min(c.remain,1048576LL));if(n>0){c.remain-=n;c.writeat=nowms();continue;}if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK||errno==EINTR))return true;if(n==0)c.remain=0;else return false;}if(!c.remain){close(c.file);c.file=-1;}}if(c.proxy)return true;if(c.closeafter)return false;c.last=nowms();parseinput(c);if(c.out.empty()&&c.file<0&&!c.proxy)return true;if(c.proxy)return true;}}
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);struct sigaction sa{};sa.sa_handler=hup;sigaction(SIGHUP,&sa,nullptr);if(argc!=3||string(argv[1])!="--config")return 1;configpath=argv[2];if(!load(configpath,cfg))return 1;rootfd=open(cfg.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(rootfd<0)return 1;listener=bindlisten(cfg.la);if(listener<0)return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;addfd(listener,EPOLLIN);globalb={(double)cfg.gb,nowms()};epoll_event events[256];while(true){int n=epoll_wait(ep,events,256,50);if(reload_flag){reload_flag=0;Config next;if(load(configpath,next)){int r=open(next.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);int ls=listener;if(next.listen!=cfg.listen)ls=bindlisten(next.la);if(r>=0&&ls>=0){if(ls!=listener){delfd(listener);listener=ls;addfd(listener,EPOLLIN);}close(rootfd);rootfd=r;cfg=next;buckets.clear();globalb={(double)cfg.gb,nowms()};}else{if(r>=0)close(r);if(ls>=0&&ls!=listener)close(ls);}}}for(int j=0;j<n;j++){int fd=events[j].data.fd;uint32_t ev=events[j].events;if(fd==listener){while(true){sockaddr_in peer{};socklen_t plen=sizeof(peer);int s=accept4(listener,(sockaddr*)&peer,&plen,SOCK_NONBLOCK|SOCK_CLOEXEC);if(s<0){if(errno==EINTR)continue;break;}if(active>=cfg.maxconn){close(s);continue;}Conn c;c.fd=s;c.peer=peer.sin_addr.s_addr;c.last=nowms();conns.emplace(s,move(c));active++;addfd(s,EPOLLIN|EPOLLRDHUP);}continue;}auto u=owners.find(fd);if(u!=owners.end()){auto it=conns.find(u->second);if(it!=conns.end()){up_event(it->second,ev);update(it->second);}continue;}auto it=conns.find(fd);if(it==conns.end())continue;Conn&c=it->second;if(ev&EPOLLIN){char b[16384];size_t room=(size_t)cfg.header+1;room=room>c.in.size()?room-c.in.size():1;ssize_t r=recv(fd,b,min(sizeof(b),room),0);if(r>0){if(c.in.empty())c.first=nowms();c.in.append(b,r);c.last=nowms();parseinput(c);}else if(r==0){destroy(fd);continue;}else if(errno!=EAGAIN&&errno!=EWOULDBLOCK&&errno!=EINTR){destroy(fd);continue;}}if((ev&EPOLLOUT)||!c.out.empty()||c.file>=0){if(!writeclient(c)){destroy(fd);continue;}}if((ev&(EPOLLERR|EPOLLHUP))&&c.out.empty()&&!c.proxy){destroy(fd);continue;}update(c);}long long t=nowms();vector<int> dead;for(auto&[fd,c]:conns){bool busy=!c.out.empty()||c.file>=0||c.proxy;if(busy){if(t-c.writeat>=cfg.wt)dead.push_back(fd);}else if(c.first){if(t-c.first>=cfg.ht)dead.push_back(fd);}else if(t-c.last>=cfg.idle)dead.push_back(fd);}for(int fd:dead)destroy(fd);}return 0;}
